<div class="page-header"><div><p class="eyebrow">TEACHING</p><h1>Lecturer assignments</h1><p>Course allocations for the relevant semester.</p></div></div>
<?php if(in_array($user['role_slug'],['administrator','academic_officer'],true)):?><section class="panel mb-4"><h2>Assign a lecturer</h2><form method="post" action="/courses/assign" data-validate><?= csrf_field() ?><div class="form-grid"><label class="form-label">Course<select class="form-select" name="course_id" required><?php foreach($courses as $r):?><option value="<?= (int)$r['id'] ?>"><?= e($r['code'].' · '.$r['title']) ?></option><?php endforeach; ?></select></label><label class="form-label">Semester<select class="form-select" name="semester_id" required><?php foreach($semesters as $r):?><option value="<?= (int)$r['id'] ?>"><?= e($r['session_name'].' · Semester '.$r['semester_number']) ?></option><?php endforeach; ?></select></label><label class="form-label">Lecturer<select class="form-select" name="lecturer_id" required><?php foreach($lecturers as $r):?><option value="<?= (int)$r['id'] ?>"><?= e($r['full_name'].' ('.$r['staff_number'].')') ?></option><?php endforeach; ?></select></label></div><button class="btn btn-primary mt-3">Assign lecturer</button></form></section><?php endif; ?>
<section class="panel"><h2>Lecturer assignments (active and inactive)</h2><div class="table-scroll"><table class="table table-clean"><thead><tr><th>Course</th><th>Title</th><th>Academic session</th><th>Semester</th><th>Lecturer</th><th>Status</th><?php if(in_array($user['role_slug'],['administrator','academic_officer'],true)):?><th>Manage</th><?php endif;?></tr></thead><tbody><?php foreach($items as $r):?><tr><td><strong><?= e($r['code']) ?></strong></td><td><?= e($r['title']) ?></td><td><?= e($r['session_name']) ?></td><td><?= e($r['semester_number']) ?></td><td><?= e($r['lecturer_name']) ?></td><td><span class="status-pill <?= e($r['status']) ?>"><?= e($r['status']) ?></span></td><?php if(in_array($user['role_slug'],['administrator','academic_officer'],true)):?><td><div class="stack"><form method="post" action="/courses/assignment/update" class="inline-actions"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><select class="form-select form-select-sm" name="lecturer_id" aria-label="Reassign lecturer"><?php foreach($lecturers as $l):?><option value="<?= (int)$l['id'] ?>" <?= (int)$l['id']===(int)$r['lecturer_id']?'selected':'' ?>><?= e($l['full_name']) ?></option><?php endforeach;?></select><button class="btn btn-outline-primary btn-sm">Reassign</button></form><form method="post" action="/courses/assignment/status"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="status" value="<?= $r['status']==='active'?'inactive':'active' ?>"><button class="btn btn-outline-secondary btn-sm"><?= $r['status']==='active'?'Unassign':'Reactivate' ?></button></form></div></td><?php endif;?></tr><?php endforeach; ?></tbody></table></div><?= page_links($page,$total,'/courses/assignments') ?></section>
